mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("n=4 edges=0->1,0->2,1->3,2->3","0,1,2,3"),
        ("n=3 edges=1->2","0,1,2"),
        ("n=3 edges=0->1,1->2","0,1,2"),
        ("n=4 edges=0->3,1->3,2->3","0,1,2,3"),
        ("n=3 edges=2->0","1,2,0"),
        ("  \nn=4 edges=0->1,0->2,1->3,2->3\n  ","0,1,2,3"),
        ("\nn=3 edges=2->0\n","1,2,0")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS kahn-topological");
}
